head.script:
scwin.__checkErr = function() {
    return temp = WebSquare.logger.getErrorLog();
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getObjById('g_ui_menu_side_label_1').innerText == 'test';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErr() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
